/* @lc app=leetcode id=3143 lang=kotlin */ class Solution { fun maxPointsInsideSquare(points: Array<IntArray>, s: String): Int = points.indices.groupBy({ s[it] }, { maxOf(Math.abs(points[it][0]), Math.abs(points[it][1])) }).values.map { it.sorted() }.let { g -> (g.filter { it.size >= 2 }.minOfOrNull { it[1] } ?: Int.MAX_VALUE).let { lim -> g.sumOf { l -> l.count { it < lim } } } } }